arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1998_06.json', 'r') as f:
    data = json.load(f)

# Print keys
def print_keys(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_keys(v, indent + 2)
    elif isinstance(d, list) and indent < 2:
        print(' ' * indent + f'List of {len(d)} items')
        if len(d) > 0 and isinstance(d[0], dict):
            print_keys(d[0], indent + 2)

print_keys(data)
"
